// Shared by the app's object links, the catalog generator, the sitemap check and the Worker.
export const SITE_ORIGIN = 'https://starview-app.com'
const SITE_NAME = 'Star View'

/** Generated by scripts/catalogs.ts; `indexable` is added at build time from public/sitemap.xml. */
export interface ObjectPage {
  name: string
  // Catalog or overlay that holds the record, so a link can load it.
  catalog: string
  description: string
  facts: [term: string, value: string][]
  // The Info article introduction, led by the article's name.
  introduction?: string
  planets?: number
  related: { id: string; name: string }[]
  indexable?: true
}

/** A record that the map merges into another catalog's record of the same object. */
export interface ObjectPageAlias {
  canonical: string
}

// Catalog IDs use lowercase letters, digits, hyphens, dots and plus signs.
const OBJECT_PATH = /^\/objects\/([a-z0-9][a-z0-9.+-]*)\/?$/
export const SITEMAP_OBJECT_URL = new RegExp(`<loc>${SITE_ORIGIN.replaceAll('.', '\\.')}/objects/([^<]+)</loc>`, 'g')

export function objectPath(id: string): string {
  return `/objects/${id}`
}

export function objectIdFromPath(pathname: string): string | null {
  let decoded: string
  try {
    decoded = decodeURIComponent(pathname)
  } catch {
    return null
  }
  return OBJECT_PATH.exec(decoded)?.[1] ?? null
}

export function objectPageTitle(name: string): string {
  return `${name} – ${SITE_NAME}`
}

const escapeHtml = (text: string) => text.replace(/[&<>"']/g, (character) => `&#${character.charCodeAt(0)};`)

// Replaces the text between a tag prefix in index.html and the following terminator.
function replaceAfter(html: string, prefix: string, terminator: string, value: string): string {
  const start = html.indexOf(prefix)
  if (start === -1) throw new Error(`Missing page tag: ${prefix}`)
  const end = html.indexOf(terminator, start + prefix.length)
  return html.slice(0, start + prefix.length) + value + html.slice(end)
}

/** Gives index.html the object's title, description and canonical URL, and a crawlable summary that the app removes once another object is selected. */
export function renderObjectPage(html: string, id: string, page: ObjectPage): string {
  const title = escapeHtml(objectPageTitle(page.name))
  const description = escapeHtml(page.description)
  const url = `${SITE_ORIGIN}${objectPath(id)}`
  const summary = [
    '<article id="object-summary" class="sr-only">',
    `<h1>${escapeHtml(page.name)}</h1>`,
    `<p>${escapeHtml(page.introduction ?? page.description)}</p>`,
    `<dl>${page.facts.map(([term, value]) => `<div><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl>`,
    page.related.length ? `<nav aria-label="System components"><ul>${page.related.map((object) =>
      `<li><a href="${escapeHtml(objectPath(object.id))}">${escapeHtml(object.name)}</a></li>`).join('')}</ul></nav>` : '',
    '</article>',
  ].join('')
  let result = replaceAfter(html, '<title>', '<', title)
  result = replaceAfter(result, '<meta name="description" content="', '"', description)
  result = replaceAfter(result, '<link rel="canonical" href="', '"', url)
  result = replaceAfter(result, '<meta property="og:title" content="', '"', title)
  result = replaceAfter(result, '<meta property="og:description" content="', '"', description)
  result = replaceAfter(result, '<meta property="og:url" content="', '"', url)
  return replaceAfter(result, '<body>', '<', summary)
}
